ACT.tmSel=el=>{S.ui.tmSel=el.dataset.v;save();render();setTimeout(()=>{const r=document.querySelector('.tm-right');if(r&&window.innerWidth<1000)r.scrollIntoView({behavior:'smooth'})},30)};
