ACT.tmDel=el=>{if(!tmIsSA()){toast('Hapus pegawai hanya untuk superadmin. Gunakan status Nonaktif.');return}const n=el.dataset.v;document.querySelectorAll('.ov').forEach(o=>o.remove());confirmDel(n,()=>{const M=actMaster(),k=kpCfg();M.pic=M.pic.filter(x=>x.n!==n);M.del=[...new Set((M.del||[]).concat(n))];/* nama bawaan daftar awal tidak muncul lagi */delete k.pt[n];if(k.ptx)delete k.ptx[n];if(k.rl)delete k.rl[n];Object.keys(k.str||{}).forEach(id=>{if(k.str[id]===n)delete k.str[id]});Object.keys(k.stp||{}).forEach(id=>{k.stp[id]=(k.stp[id]||[]).filter(x=>x!==n);if(!k.stp[id].length)delete k.stp[id]});Object.keys(k.asg).forEach(u=>{k.asg[u]=(k.asg[u]||[]).filter(x=>x!==n);if(!k.asg[u].length)delete k.asg[u]});if(S.ui.tmSel===n)S.ui.tmSel='';actMasterSave(M);try{log('Hapus PMO & CMO Kemenkeu',n)}catch(e){}render();toast(n+' dihapus. Untuk menyimpan riwayat, gunakan status Nonaktif.')},{delMsg:w=>'<p style="margin:0">Hapus <b>'+H(w)+'</b> dari daftar PMO & CMO Kemenkeu? Unit yang dipegang menjadi belum ditunjuk. <br><span class="s">Saran: bila pindah/keluar tim, gunakan status <b>Nonaktif</b> agar riwayat tetap tersimpan.</span></p>'})};
document.addEventListener('change',e=>{const t=e.target;if(t&&t.matches&&t.matches('[data-tmteam]')){S.ui.tmTeam=t.value;S.ui.tmPg=1;save();render()}});
