/* Paginasi daftar kiri (10/20/50/100/Semua), bekerja di atas hasil pencarian. */
function tmPaginate(){const L=document.querySelector('.tm-list'),G=document.querySelector('.tm-pgr');if(!L||!G)return;const items=[...L.querySelectorAll('.tm-p')],m=items.filter(b=>b.dataset.sh!=='1');
 const ps=S.ui.tmPs==='all'?Infinity:(+S.ui.tmPs||10),pages=Math.max(1,Math.ceil(m.length/ps));let pg=Math.min(Math.max(1,+S.ui.tmPg||1),pages);S.ui.tmPg=pg;const from=(pg-1)*(isFinite(ps)?ps:0),to=isFinite(ps)?from+ps:m.length;
 items.forEach(b=>b.hidden=true);m.slice(from,to).forEach(b=>b.hidden=false);
 L.querySelectorAll('.tm-gh').forEach(h=>{let n=h.nextElementSibling,any=false;while(n&&!n.classList.contains('tm-gh')){if(!n.hidden)any=true;n=n.nextElementSibling}h.hidden=!any});
 const nm=L.querySelector('.tm-nomatch');if(!m.length&&items.length){if(!nm)L.insertAdjacentHTML('beforeend','<p class="s tm-none tm-nomatch">Tidak ada yang cocok.</p>')}else if(nm)nm.remove();
 const opt=[10,20,50,100,'all'].map(v=>'<option value="'+v+'"'+(String(S.ui.tmPs||10)===String(v)?' selected':'')+'>'+(v==='all'?'Semua':v)+'</option>').join('');
 G.innerHTML=m.length?'<span class="tm-pgi">'+(from+1)+'–'+Math.min(to,m.length)+' dari '+m.length+'</span><label class="tm-pgs">Tampil <select data-tmps aria-label="Jumlah per halaman">'+opt+'</select></label><span class="tm-pgb"><button type="button" data-tmpg="'+(pg-1)+'"'+(pg<=1?' disabled':'')+' aria-label="Sebelumnya">‹</button><b>'+pg+' / '+pages+'</b><button type="button" data-tmpg="'+(pg+1)+'"'+(pg>=pages?' disabled':'')+' aria-label="Berikutnya">›</button></span>':'';
 L.scrollTop=0}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-tmpg]');if(!b||b.disabled)return;S.ui.tmPg=+b.dataset.tmpg;tmPaginate()});
document.addEventListener('change',e=>{const x=e.target.closest&&e.target.closest('[data-tmps]');if(!x)return;e.stopPropagation();S.ui.tmPs=x.value==='all'?'all':+x.value;S.ui.tmPg=1;try{save()}catch(er){}tmPaginate()},true);

